function openJournal(chunks) {
  const decoder = new TextDecoder("utf-8");

  let iterator;
  let iteratorAcquired = false;
  let sourceDone = false;
  let terminated = false;
  let closed = false;

  let returnCalled = false;
  let returnPromise = null;
  let closePromise = null;

  let buffer = "";
  let lineNumber = 1;
  let nextInProgress = false;

  function doneResult() {
    return { done: true, value: undefined };
  }

  function acquireIterator() {
    if (!iteratorAcquired) {
      const getIterator = chunks[Symbol.asyncIterator];
      if (typeof getIterator !== "function") {
        throw new TypeError("chunks must be an async iterable");
      }
      iterator = getIterator.call(chunks);
      iteratorAcquired = true;
    }
    return iterator;
  }

  function callReturn() {
    if (returnPromise) return returnPromise;
    if (!iteratorAcquired || sourceDone || returnCalled) {
      return Promise.resolve();
    }

    returnCalled = true;
    returnPromise = (async function () {
      const method = iterator && iterator.return;
      if (typeof method === "function") {
        await method.call(iterator);
      }
    })();

    return returnPromise;
  }

  async function terminateAfterReadError(error) {
    terminated = true;
    try {
      await callReturn();
    } catch (_) {
      // Preserve the original read error.
    }
  }

  function parseLine(text, line) {
    if (/^[ \t]*$/.test(text)) {
      return null;
    }

    try {
      return {
        line,
        ok: true,
        value: JSON.parse(text)
      };
    } catch (_) {
      return {
        line,
        ok: false,
        text
      };
    }
  }

  async function next() {
    if (closed || terminated || sourceDone) {
      return doneResult();
    }

    if (nextInProgress) {
      throw new TypeError("next() calls must not overlap");
    }

    nextInProgress = true;

    try {
      while (true) {
        if (closed || terminated) {
          return doneResult();
        }

        const newlineIndex = buffer.indexOf("\n");

        if (newlineIndex !== -1) {
          let text = buffer.slice(0, newlineIndex);
          buffer = buffer.slice(newlineIndex + 1);

          if (text.endsWith("\r")) {
            text = text.slice(0, -1);
          }

          const event = parseLine(text, lineNumber++);
          if (event !== null) {
            return { done: false, value: event };
          }

          continue;
        }

        if (sourceDone) {
          if (buffer.length === 0) {
            return doneResult();
          }

          const text = buffer;
          buffer = "";

          const event = parseLine(text, lineNumber++);
          if (event !== null) {
            return { done: false, value: event };
          }

          continue;
        }

        let source;
        try {
          source = acquireIterator();
        } catch (error) {
          terminated = true;
          throw error;
        }

        let result;
        try {
          result = await source.next();
        } catch (error) {
          await terminateAfterReadError(error);
          throw error;
        }

        if (closed || terminated) {
          return doneResult();
        }

        if (result.done) {
          sourceDone = true;
          buffer += decoder.decode();
        } else {
          try {
            buffer += decoder.decode(result.value, { stream: true });
          } catch (error) {
            await terminateAfterReadError(error);
            throw error;
          }
        }
      }
    } finally {
      nextInProgress = false;
    }
  }

  function close() {
    if (closePromise) {
      return closePromise;
    }

    closed = true;
    closePromise = callReturn();
    return closePromise;
  }

  return { next, close };
}
